import type { BridgeRuntime } from '../core-types';
import type { BridgeInteractionState } from './local-types';
import { createPullToRefreshOverlay, PULL_TO_REFRESH_THRESHOLD } from './pull-to-refresh';
import { computeModifiers, handleToBigInt } from './utils/encoding';
import { writeUtf8ToHeap } from './utils/heap';

const DEFAULT_LOGICAL_WIDTH = 320;
const DEFAULT_LOGICAL_HEIGHT = 220;
const UI_EVENT_POINTER_DOWN = 1;
const UI_EVENT_POINTER_UP = 2;
const UI_EVENT_POINTER_MOVE = 3;
const UI_EVENT_POINTER_LEAVE = 5;
const UI_KEY_EVENT_DOWN = 1;
const UI_KEY_EVENT_UP = 2;
const EDGE_AUTOSCROLL_THRESHOLD = 30;
const TOUCH_SCROLL_THRESHOLD = 8;
const TOUCH_AXIS_LOCK_DOMINANCE_RATIO = 1.25;
const TOUCH_AXIS_BREAKOUT_DISTANCE = 32;
const TOUCH_AXIS_BREAKOUT_RATIO = 0.72;
const TOUCH_AXIS_BREAKOUT_STEP_THRESHOLD = 8;

function resolvePrimaryTouchAxis(deltaX: number, deltaY: number): 'x' | 'y' {
  const absX = Math.abs(deltaX);
  const absY = Math.abs(deltaY);
  if (absX >= absY * TOUCH_AXIS_LOCK_DOMINANCE_RATIO) {
    return 'x';
  }
  if (absY >= absX * TOUCH_AXIS_LOCK_DOMINANCE_RATIO) {
    return 'y';
  }
  return absX >= absY ? 'x' : 'y';
}

function shouldUnlockTouchAxis(axisMode: 'x' | 'y' | 'xy' | null, travelX: number, travelY: number): boolean {
  if (axisMode === null || axisMode === 'xy') {
    return false;
  }
  const primaryTravel = axisMode === 'x' ? travelX : travelY;
  const secondaryTravel = axisMode === 'x' ? travelY : travelX;
  if (primaryTravel < TOUCH_AXIS_BREAKOUT_DISTANCE || secondaryTravel < TOUCH_AXIS_BREAKOUT_DISTANCE) {
    return false;
  }
  return secondaryTravel >= TOUCH_AXIS_BREAKOUT_DISTANCE &&
    secondaryTravel >= primaryTravel * TOUCH_AXIS_BREAKOUT_RATIO;
}

function currentInteractionTimeMs(): bigint {
  return BigInt(Math.floor(performance.now()));
}

function pointInSemanticBounds(
  bounds: { readonly x: number; readonly y: number; readonly width: number; readonly height: number },
  x: number,
  y: number,
): boolean {
  return x >= bounds.x &&
    x <= (bounds.x + bounds.width) &&
    y >= bounds.y &&
    y <= (bounds.y + bounds.height);
}

function findSemanticTextboxHandleAtPoint(runtime: BridgeRuntime, x: number, y: number): bigint {
  const tree = runtime.getSemanticTree();
  for (let i = tree.length - 1; i >= 0; i -= 1) {
    const node = tree[i];
    if (node?.roleName !== 'textbox') {
      continue;
    }
    if (pointInSemanticBounds(node.bounds, x, y)) {
      return handleToBigInt(node.handle);
    }
  }
  return 0n;
}

function semanticRoleAtHandle(runtime: BridgeRuntime, handle: bigint): string | null {
  const handleKey = handle.toString();
  const node = runtime.getSemanticTree().find((entry) => entry.handle === handleKey);
  return node?.roleName ?? null;
}

export function ensureCanvasLogicalSize(canvas: HTMLCanvasElement): void {
  const rect = canvas.getBoundingClientRect();
  if (rect.width <= 0 || rect.height <= 0) {
    canvas.style.width = `${String(DEFAULT_LOGICAL_WIDTH)}px`;
    canvas.style.height = `${String(DEFAULT_LOGICAL_HEIGHT)}px`;
  }
}

export function getCanvasSizeSource(canvas: HTMLCanvasElement): HTMLElement | HTMLCanvasElement {
  const source = canvas.closest('[data-effindom-canvas-size-source]');
  return source instanceof HTMLElement ? source : canvas;
}

export function readCanvasLogicalSize(canvas: HTMLCanvasElement): { readonly width: number; readonly height: number } {
  const sizeSource = getCanvasSizeSource(canvas);
  if (sizeSource.clientWidth > 0 && sizeSource.clientHeight > 0) {
    return {
      width: sizeSource.clientWidth,
      height: sizeSource.clientHeight,
    };
  }
  const styleWidth = Number.parseFloat(canvas.style.width);
  const styleHeight = Number.parseFloat(canvas.style.height);
  if (Number.isFinite(styleWidth) && styleWidth > 0 && Number.isFinite(styleHeight) && styleHeight > 0) {
    return { width: styleWidth, height: styleHeight };
  }
  return {
    width: canvas.clientWidth || DEFAULT_LOGICAL_WIDTH,
    height: canvas.clientHeight || DEFAULT_LOGICAL_HEIGHT,
  };
}

function getPointerPosition(
  canvas: HTMLCanvasElement,
  event: { readonly clientX: number; readonly clientY: number },
): { readonly x: number; readonly y: number } {
  const sizeSource = getCanvasSizeSource(canvas);
  const rect = sizeSource.getBoundingClientRect();
  const logicalSize = readCanvasLogicalSize(canvas);
  const contentLeft = rect.left + sizeSource.clientLeft;
  const contentTop = rect.top + sizeSource.clientTop;
  const displayWidth = sizeSource.clientWidth || (rect.width - (sizeSource.clientLeft + sizeSource.clientLeft)) || DEFAULT_LOGICAL_WIDTH;
  const displayHeight = sizeSource.clientHeight || (rect.height - (sizeSource.clientTop + sizeSource.clientTop)) || DEFAULT_LOGICAL_HEIGHT;
  const x = displayWidth > 0 ? ((event.clientX - contentLeft) / displayWidth) * logicalSize.width : 0;
  const y = displayHeight > 0 ? ((event.clientY - contentTop) / displayHeight) * logicalSize.height : 0;
  return { x, y };
}

function isPointerInsideCanvas(
  canvas: HTMLCanvasElement,
  event: { readonly clientX: number; readonly clientY: number },
): boolean {
  const rect = getCanvasSizeSource(canvas).getBoundingClientRect();
  return event.clientX >= rect.left &&
    event.clientX <= rect.right &&
    event.clientY >= rect.top &&
    event.clientY <= rect.bottom;
}

function normalizeWheelDelta(event: WheelEvent, canvas: HTMLCanvasElement): { readonly x: number; readonly y: number } {
  let deltaX = event.deltaX;
  let deltaY = event.deltaY;
  if (event.deltaMode === WheelEvent.DOM_DELTA_LINE) {
    deltaX *= 16.0;
    deltaY *= 16.0;
  } else if (event.deltaMode === WheelEvent.DOM_DELTA_PAGE) {
    const logicalSize = readCanvasLogicalSize(canvas);
    deltaX *= logicalSize.width;
    deltaY *= logicalSize.height;
  }
  if (event.shiftKey && Math.abs(deltaX) < 0.001 && Math.abs(deltaY) > 0.0) {
    return { x: deltaY, y: 0.0 };
  }
  return { x: deltaX, y: deltaY };
}

function detectCoarsePointerMode(): boolean {
  return window.matchMedia('(pointer: coarse)').matches || navigator.maxTouchPoints > 0;
}

function detectPlatformFamily(): number {
  const navigatorWithUserAgentData = navigator as Navigator & {
    userAgentData?: {
      platform?: string;
    };
  };
  const platform = (
    navigatorWithUserAgentData.userAgentData?.platform ??
    navigator.platform ??
    navigator.userAgent
  ).toLowerCase();
  if (
    platform.includes('mac') ||
    platform.includes('iphone') ||
    platform.includes('ipad') ||
    platform.includes('ipod') ||
    platform.includes('ios')
  ) {
    return 1;
  }
  if (platform.includes('win')) {
    return 2;
  }
  if (
    platform.includes('linux') ||
    platform.includes('android') ||
    platform.includes('x11') ||
    platform.includes('cros')
  ) {
    return 3;
  }
  return 0;
}

function isVerticalCanvasNavigationKey(key: string): boolean {
  return key === 'ArrowUp' ||
    key === 'ArrowDown' ||
    key === 'PageUp' ||
    key === 'PageDown' ||
    key === 'Home' ||
    key === 'End';
}

function isTextNavigationKey(key: string): boolean {
  return key === 'ArrowLeft' ||
    key === 'ArrowRight' ||
    key === 'ArrowUp' ||
    key === 'ArrowDown' ||
    key === 'PageUp' ||
    key === 'PageDown' ||
    key === 'Home' ||
    key === 'End';
}

export function installEventHandlers(runtime: BridgeRuntime, interactionState: BridgeInteractionState): () => void {
  const { canvas, ui } = runtime;
  canvas.tabIndex = 0;
  canvas.style.touchAction = 'none';
  canvas.style.outline = 'none';
  const coarsePointerQuery = window.matchMedia('(pointer: coarse)');
  const updateCoarsePointerMode = (): void => {
    ui._ui_set_coarse_pointer_mode(detectCoarsePointerMode() ? 1 : 0);
  };
  const updatePlatformFamily = (): void => {
    ui._ui_set_platform_family(detectPlatformFamily());
  };
  updateCoarsePointerMode();
  updatePlatformFamily();
  const pullToRefresh = createPullToRefreshOverlay();
  coarsePointerQuery.addEventListener?.('change', updateCoarsePointerMode);
  let primaryPointerDown = false;
  let activePrimaryPointerId: number | null = null;
  let suppressedContextMenuPointerId: number | null = null;
  let edgeAutoScrollTickScheduled = false;
  let pointerMoveFrameScheduled = false;
  let activePrimaryPointerType: string | null = null;
  let activeTouchGesture: {
    pointerId: number;
    startX: number;
    startY: number;
    lastX: number;
    lastY: number;
    scrolling: boolean;
    breakoutTravelX: number;
    breakoutTravelY: number;
    axisMode: 'x' | 'y' | 'xy' | null;
    pullToRefreshEligible: boolean;
    pullToRefreshCaptured: boolean;
    pullToRefreshDistance: number;
  } | null = null;
  let pendingPointerMove: {
    handle: bigint;
    x: number;
    y: number;
    clientX: number;
    clientY: number;
    pointerInsideCanvas: boolean;
    modifiers: number;
  } | null = null;

  const applySelectionAutoScroll = (x: number, y: number): void => {
    if (!primaryPointerDown || activePrimaryPointerType === 'touch') {
      return;
    }
    if (handleToBigInt(ui._ui_selection_autoscroll(x, y, EDGE_AUTOSCROLL_THRESHOLD)) === 0n) {
      return;
    }
    runtime.flushPendingCommit();
    runtime.requestFrame();
  };

  const processPointerMove = (pending: NonNullable<typeof pendingPointerMove>): void => {
    interactionState.setPointerInsideCanvas(pending.pointerInsideCanvas);
    interactionState.setLastPointerClientPosition(pending.clientX, pending.clientY);
    interactionState.setLastPointerPosition(pending.x, pending.y);
    ui._ui_set_interaction_time(currentInteractionTimeMs());
    ui._ui_on_pointer_event(UI_EVENT_POINTER_MOVE, pending.handle, pending.x, pending.y);
    runtime.commitFrame();
    if (pending.handle === 0n) {
      const appCapturedHandle = runtime.getCapturedPointerHandle();
      if (appCapturedHandle !== null) {
        window.__effindomCallbacks?.onPointerEventWithCoords?.(UI_EVENT_POINTER_MOVE, appCapturedHandle, pending.x, pending.y, pending.modifiers);
      }
    }
    applySelectionAutoScroll(pending.x, pending.y);
    scheduleEdgeAutoScrollTick();
  };

  const schedulePointerMoveFlush = (): void => {
    if (pointerMoveFrameScheduled) {
      return;
    }
    pointerMoveFrameScheduled = true;
    requestAnimationFrame(() => {
      pointerMoveFrameScheduled = false;
      const pending = pendingPointerMove;
      pendingPointerMove = null;
      if (pending === null) {
        return;
      }
      processPointerMove(pending);
      if (pendingPointerMove !== null) {
        schedulePointerMoveFlush();
      }
    });
  };

  const scheduleEdgeAutoScrollTick = (): void => {
    if (edgeAutoScrollTickScheduled || !primaryPointerDown || activePrimaryPointerType === 'touch') {
      return;
    }
    edgeAutoScrollTickScheduled = true;
    requestAnimationFrame(() => {
      edgeAutoScrollTickScheduled = false;
      if (!primaryPointerDown) {
        return;
      }
      const { x, y } = interactionState.getLastPointerPosition();
      if (handleToBigInt(ui._ui_selection_autoscroll(x, y, EDGE_AUTOSCROLL_THRESHOLD)) === 0n) {
        return;
      }
      runtime.commitFrame();
      runtime.flushPendingCommit();
      runtime.requestFrame();
      scheduleEdgeAutoScrollTick();
    });
  };

  const releaseCanvasPointerCapture = (pointerId: number): void => {
    if (canvas.hasPointerCapture(pointerId)) {
      canvas.releasePointerCapture(pointerId);
    }
  };

  const captureCanvasPointer = (pointerId: number): void => {
    try {
      canvas.setPointerCapture(pointerId);
    } catch {
      // Synthetic touch events in tests and some browser/device combinations can reject explicit capture.
    }
  };

  const cancelPressedPointerInteraction = (x: number, y: number): void => {
    const capturedHandle = interactionState.getCapturedPointerHandle();
    interactionState.setCapturedPointerHandle(null);
    primaryPointerDown = false;
    activePrimaryPointerId = null;
    activePrimaryPointerType = null;
    pendingPointerMove = null;
    ui._ui_set_interaction_time(currentInteractionTimeMs());
    ui._ui_on_pointer_event(UI_EVENT_POINTER_LEAVE, capturedHandle ?? 0n, x, y);
    runtime.commitFrame();
  };

  const handleTouchPointerScroll = (event: PointerEvent, position: { readonly x: number; readonly y: number }, modifiers: number): boolean => {
    if (event.pointerType !== 'touch' || activeTouchGesture === null || activeTouchGesture.pointerId !== event.pointerId) {
      return false;
    }

    const deltaFromStartX = position.x - activeTouchGesture.startX;
    const deltaFromStartY = position.y - activeTouchGesture.startY;

    if (!activeTouchGesture.scrolling) {
      if ((deltaFromStartX * deltaFromStartX) + (deltaFromStartY * deltaFromStartY) < TOUCH_SCROLL_THRESHOLD * TOUCH_SCROLL_THRESHOLD) {
        event.preventDefault();
        return true;
      }
      activeTouchGesture.scrolling = true;
      const primaryAxis = resolvePrimaryTouchAxis(deltaFromStartX, deltaFromStartY);
      activeTouchGesture.axisMode = primaryAxis;
      activeTouchGesture.pullToRefreshEligible = primaryAxis === 'y';
      cancelPressedPointerInteraction(position.x, position.y);
      ui._ui_touch_scroll_begin(
        runtime.getHandleFromPoint(activeTouchGesture.startX, activeTouchGesture.startY),
        activeTouchGesture.startX,
        activeTouchGesture.startY,
      );
    }

    const deltaX = activeTouchGesture.lastX - position.x;
    const deltaY = activeTouchGesture.lastY - position.y;
    const absDeltaX = Math.abs(deltaX);
    const absDeltaY = Math.abs(deltaY);
    activeTouchGesture.lastX = position.x;
    activeTouchGesture.lastY = position.y;
    if (absDeltaX >= TOUCH_AXIS_BREAKOUT_STEP_THRESHOLD && absDeltaY >= TOUCH_AXIS_BREAKOUT_STEP_THRESHOLD) {
      activeTouchGesture.breakoutTravelX += absDeltaX;
      activeTouchGesture.breakoutTravelY += absDeltaY;
    } else {
      activeTouchGesture.breakoutTravelX = 0.0;
      activeTouchGesture.breakoutTravelY = 0.0;
    }
    if (shouldUnlockTouchAxis(
      activeTouchGesture.axisMode,
      activeTouchGesture.breakoutTravelX,
      activeTouchGesture.breakoutTravelY,
    )) {
      activeTouchGesture.axisMode = 'xy';
      activeTouchGesture.pullToRefreshEligible = false;
      activeTouchGesture.pullToRefreshCaptured = false;
      activeTouchGesture.pullToRefreshDistance = 0.0;
    }
    const scrollDeltaX = activeTouchGesture.axisMode === 'x' || activeTouchGesture.axisMode === 'xy' ? deltaX : 0.0;
    const scrollDeltaY = activeTouchGesture.axisMode === 'y' || activeTouchGesture.axisMode === 'xy' ? deltaY : 0.0;
    const canCapturePullToRefresh =
      activeTouchGesture.pullToRefreshEligible &&
      deltaFromStartY > 0.0 &&
      ui._ui_touch_scroll_allows_pull_to_refresh() !== 0;
    if (canCapturePullToRefresh) {
      activeTouchGesture.pullToRefreshCaptured = true;
    }
    activeTouchGesture.pullToRefreshDistance = activeTouchGesture.pullToRefreshCaptured
      ? Math.max(0.0, deltaFromStartY)
      : 0.0;
    if (activeTouchGesture.pullToRefreshCaptured) {
      pullToRefresh.show(activeTouchGesture.pullToRefreshDistance);
    } else {
      pullToRefresh.hide();
    }
    const appliedScrollDeltaY = activeTouchGesture.pullToRefreshCaptured ? 0.0 : scrollDeltaY;

    interactionState.setPointerInsideCanvas(isPointerInsideCanvas(canvas, event));
    interactionState.setLastPointerClientPosition(event.clientX, event.clientY);
    interactionState.setLastPointerPosition(position.x, position.y);
    interactionState.setLastPointerModifiers(modifiers);
    ui._ui_set_interaction_time(currentInteractionTimeMs());
    ui._ui_on_pointer_event(UI_EVENT_POINTER_MOVE, runtime.getHandleFromPoint(position.x, position.y), position.x, position.y);
    ui._ui_touch_scroll_update(scrollDeltaX, appliedScrollDeltaY);
    runtime.commitFrame();
    event.preventDefault();
    return true;
  };

  const forwardPointerEvent = (type: number, useHitTest = true) => (event: PointerEvent): void => {
    const modifiers = computeModifiers(event);
    const pointerInsideCanvas = type === UI_EVENT_POINTER_LEAVE ? false : isPointerInsideCanvas(canvas, event);
    const position = getPointerPosition(canvas, event);
    if (event.pointerType === 'touch' && event.cancelable) {
      // Real mobile browsers can still intermittently let canvas touches drift into
      // native gesture handling unless we claim the stream from pointerdown onward.
      event.preventDefault();
    }
    if (type === UI_EVENT_POINTER_DOWN && event.button === 2) {
      window.__effindomCallbacks?.onBeforeContextMenuHitTest?.();
      const handle = runtime.getHandleFromPoint(position.x, position.y);
      const activeTextHandle = interactionState.getActiveTextHandle();
      const refocusActiveTextInputAfterContextMenu =
        activeTextHandle !== null &&
        handle === activeTextHandle;
      suppressedContextMenuPointerId = event.pointerId;
      interactionState.setPointerInsideCanvas(pointerInsideCanvas);
      interactionState.setLastPointerClientPosition(event.clientX, event.clientY);
      interactionState.setLastPointerPosition(position.x, position.y);
      interactionState.setLastPointerModifiers(modifiers);
      if (!refocusActiveTextInputAfterContextMenu) {
        canvas.focus({ preventScroll: true });
      }
      ui._ui_set_interaction_time(currentInteractionTimeMs());
      window.__effindomCallbacks?.onContextMenu?.(
        handle,
        position.x,
        position.y,
      );
      if (refocusActiveTextInputAfterContextMenu) {
        interactionState.refocusActiveTextInput();
      }
      event.preventDefault();
      return;
    }
    if (suppressedContextMenuPointerId === event.pointerId) {
      interactionState.setPointerInsideCanvas(pointerInsideCanvas);
      interactionState.setLastPointerClientPosition(event.clientX, event.clientY);
      interactionState.setLastPointerPosition(position.x, position.y);
      interactionState.setLastPointerModifiers(modifiers);
      if (type === UI_EVENT_POINTER_UP || type === UI_EVENT_POINTER_LEAVE) {
        suppressedContextMenuPointerId = null;
      }
      event.preventDefault();
      return;
    }
    if (type === UI_EVENT_POINTER_DOWN) {
      captureCanvasPointer(event.pointerId);
      primaryPointerDown = true;
      activePrimaryPointerId = event.pointerId;
      activePrimaryPointerType = event.pointerType;
      if (event.pointerType === 'touch') {
        activeTouchGesture = {
          pointerId: event.pointerId,
          startX: position.x,
          startY: position.y,
          lastX: position.x,
          lastY: position.y,
          scrolling: false,
          breakoutTravelX: 0.0,
          breakoutTravelY: 0.0,
          axisMode: null,
          pullToRefreshEligible: false,
          pullToRefreshCaptured: false,
          pullToRefreshDistance: 0.0,
        };
      }
    } else if (activeTouchGesture !== null && activeTouchGesture.pointerId === event.pointerId) {
      if (type === UI_EVENT_POINTER_MOVE && handleTouchPointerScroll(event, position, modifiers)) {
        return;
      }
      if (type === UI_EVENT_POINTER_UP || type === UI_EVENT_POINTER_LEAVE) {
        const scrolling = activeTouchGesture.scrolling;
        const triggerRefresh = activeTouchGesture.pullToRefreshDistance >= PULL_TO_REFRESH_THRESHOLD;
        activeTouchGesture = null;
        if (scrolling) {
          interactionState.setCapturedPointerHandle(null);
          primaryPointerDown = false;
          activePrimaryPointerId = null;
          activePrimaryPointerType = null;
          pendingPointerMove = null;
          ui._ui_touch_scroll_end();
          if (triggerRefresh) {
            pullToRefresh.hide(true);
            window.location.reload();
          } else {
            pullToRefresh.hide();
          }
          releaseCanvasPointerCapture(event.pointerId);
          event.preventDefault();
          return;
        }
        pullToRefresh.hide(true);
      }
    }
    const capturedHandle = interactionState.getCapturedPointerHandle();
    const activeTextHandle = interactionState.getActiveTextHandle();
    const rawHitHandle = useHitTest ? runtime.getHandleFromPoint(position.x, position.y) : 0n;
    const semanticTextboxHandle =
      (type === UI_EVENT_POINTER_DOWN || activeTextHandle !== null) && useHitTest
        ? findSemanticTextboxHandleAtPoint(runtime, position.x, position.y)
        : 0n;
    const shouldPreferSemanticTextbox =
      semanticTextboxHandle !== 0n &&
      (rawHitHandle === 0n || semanticRoleAtHandle(runtime, rawHitHandle) !== 'textbox') &&
      (type === UI_EVENT_POINTER_DOWN ||
        semanticTextboxHandle === activeTextHandle ||
        semanticTextboxHandle === capturedHandle);
    const hitHandle = shouldPreferSemanticTextbox ? semanticTextboxHandle : rawHitHandle;
    const handle = type === UI_EVENT_POINTER_DOWN
      ? hitHandle
      : ((useHitTest && pointerInsideCanvas) ? hitHandle : (capturedHandle ?? hitHandle));
    const refocusActiveTextInputAfterPointerDown =
      type === UI_EVENT_POINTER_DOWN &&
      activeTextHandle !== null &&
      handle === activeTextHandle;
    const delayCanvasFocusUntilAfterPointerDown =
      type === UI_EVENT_POINTER_DOWN &&
      activeTextHandle !== null &&
      handle !== activeTextHandle;
    const refocusActiveTextInputAfterPointerUp =
      type === UI_EVENT_POINTER_UP &&
      activeTextHandle !== null &&
      handle === activeTextHandle;
    if ((type === UI_EVENT_POINTER_UP || type === UI_EVENT_POINTER_LEAVE) && pendingPointerMove !== null) {
      const pending = pendingPointerMove;
      pendingPointerMove = null;
      processPointerMove(pending);
    }
    if (type === UI_EVENT_POINTER_DOWN) {
      interactionState.setPointerInsideCanvas(pointerInsideCanvas);
      interactionState.setLastPointerClientPosition(event.clientX, event.clientY);
      interactionState.setLastPointerPosition(position.x, position.y);
      interactionState.setLastPointerModifiers(modifiers);
      if (!refocusActiveTextInputAfterPointerDown && !delayCanvasFocusUntilAfterPointerDown) {
        canvas.focus({ preventScroll: true });
      }
      ui._ui_set_interaction_time(currentInteractionTimeMs());
      interactionState.setCapturedPointerHandle(handle === 0n ? null : handle);
      ui._ui_on_pointer_event(type, handle, position.x, position.y);
      runtime.commitFrame();
      if (delayCanvasFocusUntilAfterPointerDown && interactionState.getActiveTextHandle() === null) {
        canvas.focus({ preventScroll: true });
      }
      if (refocusActiveTextInputAfterPointerDown) {
        interactionState.refocusActiveTextInput();
      } else if (interactionState.getActiveTextHandle() !== null && !interactionState.isActiveTextInputFocused()) {
        interactionState.refocusActiveTextInput();
      }
      scheduleEdgeAutoScrollTick();
    } else if (type === UI_EVENT_POINTER_MOVE && primaryPointerDown) {
      pendingPointerMove = {
        handle,
        x: position.x,
        y: position.y,
        clientX: event.clientX,
        clientY: event.clientY,
        pointerInsideCanvas,
        modifiers,
      };
      schedulePointerMoveFlush();
      return;
    } else {
      interactionState.setPointerInsideCanvas(pointerInsideCanvas);
      interactionState.setLastPointerClientPosition(event.clientX, event.clientY);
      interactionState.setLastPointerPosition(position.x, position.y);
      interactionState.setLastPointerModifiers(modifiers);
      ui._ui_set_interaction_time(currentInteractionTimeMs());
      ui._ui_on_pointer_event(type, handle, position.x, position.y);
      runtime.commitFrame();
      if (refocusActiveTextInputAfterPointerUp) {
        interactionState.refocusActiveTextInput();
      } else if (interactionState.getActiveTextHandle() !== null && !interactionState.isActiveTextInputFocused()) {
        interactionState.refocusActiveTextInput();
      }
      if (handle === 0n) {
        const appCapturedHandle = runtime.getCapturedPointerHandle();
        if (appCapturedHandle !== null) {
          window.__effindomCallbacks?.onPointerEventWithCoords?.(type, appCapturedHandle, position.x, position.y, modifiers);
        }
      }
      scheduleEdgeAutoScrollTick();
    }
    if (type === UI_EVENT_POINTER_UP || type === UI_EVENT_POINTER_LEAVE) {
      primaryPointerDown = false;
      activePrimaryPointerId = null;
      activePrimaryPointerType = null;
      interactionState.setCapturedPointerHandle(null);
    }
    if ((type === UI_EVENT_POINTER_UP || type === UI_EVENT_POINTER_LEAVE)) {
      releaseCanvasPointerCapture(event.pointerId);
    }
  };

  const handleContextMenu = (event: Event): void => {
    event.preventDefault();
  };
  const handlePointerDown = forwardPointerEvent(UI_EVENT_POINTER_DOWN);
  const handlePointerUp = forwardPointerEvent(UI_EVENT_POINTER_UP);
  const handlePointerMove = forwardPointerEvent(UI_EVENT_POINTER_MOVE);
  const handleCapturedPointerExit = (event: PointerEvent): void => {
    if (canvas.hasPointerCapture(event.pointerId)) {
      if (primaryPointerDown) {
        forwardPointerEvent(UI_EVENT_POINTER_MOVE, false)(event);
      }
      return;
    }
    forwardPointerEvent(UI_EVENT_POINTER_LEAVE, false)(event);
  };
  const handlePointerLeave = (event: PointerEvent): void => {
    handleCapturedPointerExit(event);
  };
  const handlePointerOut = (event: PointerEvent): void => {
    handleCapturedPointerExit(event);
  };
  const handlePointerCancel = (event: PointerEvent): void => {
    forwardPointerEvent(UI_EVENT_POINTER_LEAVE, false)(event);
  };
  const shouldHandleWindowPointerEvent = (event: PointerEvent): boolean => {
    return primaryPointerDown &&
      activePrimaryPointerId !== null &&
      event.pointerId === activePrimaryPointerId &&
      event.target !== canvas;
  };
  const handleWindowPointerMove = (event: PointerEvent): void => {
    if (!shouldHandleWindowPointerEvent(event)) {
      return;
    }
    handlePointerMove(event);
  };
  const handleWindowPointerUp = (event: PointerEvent): void => {
    if (!shouldHandleWindowPointerEvent(event)) {
      return;
    }
    handlePointerUp(event);
  };
  const handleWindowPointerCancel = (event: PointerEvent): void => {
    if (!shouldHandleWindowPointerEvent(event)) {
      return;
    }
    handlePointerCancel(event);
  };
  const handleWheel = (event: WheelEvent): void => {
    event.preventDefault();
    const position = getPointerPosition(canvas, event);
    interactionState.setPointerInsideCanvas(isPointerInsideCanvas(canvas, event));
    interactionState.setLastPointerClientPosition(event.clientX, event.clientY);
    interactionState.setLastPointerPosition(position.x, position.y);
    interactionState.setLastPointerModifiers(computeModifiers(event));
    ui._ui_set_interaction_time(currentInteractionTimeMs());
    const handle = runtime.getHandleFromPoint(position.x, position.y);
    ui._ui_on_pointer_event(UI_EVENT_POINTER_MOVE, handle, position.x, position.y);
    const delta = normalizeWheelDelta(event, canvas);
    ui._ui_on_wheel_event(delta.x, delta.y);
    runtime.commitFrame();
  };

  const forwardKeyEvent = (type: number) => (event: KeyboardEvent): void => {
    const modifiers = computeModifiers(event);
    const activeTextHandle = interactionState.getActiveTextHandle();
    const activeTextEditable = interactionState.getActiveTextEditable();
    const activeTextMultiline = interactionState.getActiveTextMultiline();
    const activeTextInputFocused = interactionState.isActiveTextInputFocused();
    const activeEditableTextOwnsNativeEditingKey =
      activeTextHandle !== null &&
      activeTextEditable &&
      activeTextInputFocused &&
      !event.ctrlKey &&
      !event.metaKey &&
      !event.altKey &&
      (
        event.key.length === 1 ||
        (activeTextMultiline && event.key === 'Enter') ||
        event.key === 'Backspace' ||
        event.key === 'Delete'
      );
    const activeEditableTextNeedsRuntimeEditingFallback =
      activeTextHandle !== null &&
      activeTextEditable &&
      !activeTextInputFocused &&
      !event.ctrlKey &&
      !event.metaKey &&
      !event.altKey &&
      (
        event.key.length === 1 ||
        (activeTextMultiline && event.key === 'Enter') ||
        event.key === 'Backspace' ||
        event.key === 'Delete'
      );
    if (activeEditableTextOwnsNativeEditingKey) {
      if (
          type === UI_KEY_EVENT_DOWN &&
          (event.key === 'Backspace' || event.key === 'Delete') &&
          interactionState.applyActiveTextDeletion(event.key === 'Delete')) {
        event.preventDefault();
      }
      return;
    }
    const activeTextOwnsRuntimeNavigationKey =
      activeTextHandle !== null &&
      isTextNavigationKey(event.key);
    const activeReadonlyTextOwnsRuntimeKey =
      activeTextHandle !== null &&
      !activeTextEditable &&
      (
        event.key.length === 1 ||
        event.key === 'Backspace' ||
        event.key === 'Delete' ||
        isTextNavigationKey(event.key)
      );
    if (
      activeEditableTextNeedsRuntimeEditingFallback ||
      activeTextOwnsRuntimeNavigationKey ||
      activeReadonlyTextOwnsRuntimeKey
    ) {
      event.preventDefault();
    }
    ui._ui_set_interaction_time(currentInteractionTimeMs());
    const shouldAlwaysPreventDefault =
      event.key === 'Tab' ||
      ((event.ctrlKey || event.metaKey) &&
        (
          event.key === 'c' || event.key === 'C' ||
          event.key === 'a' || event.key === 'A' ||
          event.key === 'x' || event.key === 'X' ||
          event.key === 'v' || event.key === 'V' ||
          event.key === 'z' || event.key === 'Z' ||
          event.key === 'y' || event.key === 'Y'
        ))
    ;
    if (shouldAlwaysPreventDefault) {
      event.preventDefault();
    }
    const heapString = writeUtf8ToHeap(ui, event.key);
    let callbackHandled = false;
    try {
      ui._ui_on_key_event(type, heapString.ptr, heapString.len, modifiers);
      if (
        !activeEditableTextNeedsRuntimeEditingFallback &&
        !activeTextOwnsRuntimeNavigationKey &&
        !activeReadonlyTextOwnsRuntimeKey
      ) {
        callbackHandled = window.__effindomCallbacks?.onKeyEventWithKey?.(type, event.key, modifiers) === true;
      }
    } finally {
      heapString.dispose();
    }
    if (
      type === UI_KEY_EVENT_DOWN &&
      (
        callbackHandled ||
        (!event.ctrlKey && !event.altKey && !event.metaKey && isVerticalCanvasNavigationKey(event.key))
      )
    ) {
      event.preventDefault();
    }
    runtime.commitFrame();
    if (interactionState.getActiveTextHandle() !== null && !interactionState.isActiveTextInputFocused()) {
      interactionState.refocusActiveTextInput();
    }
  };

  const handleKeyDown = forwardKeyEvent(UI_KEY_EVENT_DOWN);
  const handleKeyUp = forwardKeyEvent(UI_KEY_EVENT_UP);
  const handleWindowBlur = (): void => {
    if (interactionState.getActiveTextHandle() === null) {
      return;
    }
    ui._ui_request_focus(0n);
    runtime.commitFrame();
  };
  const handleResize = (): void => {
    runtime.updateCanvasSize();
    runtime.commitFrame();
  };

  canvas.addEventListener('contextmenu', handleContextMenu);
  canvas.addEventListener('pointerdown', handlePointerDown, { passive: false });
  canvas.addEventListener('pointerup', handlePointerUp, { passive: false });
  canvas.addEventListener('pointermove', handlePointerMove, { passive: false });
  canvas.addEventListener('pointerleave', handlePointerLeave, { passive: false });
  canvas.addEventListener('pointerout', handlePointerOut, { passive: false });
  canvas.addEventListener('pointercancel', handlePointerCancel, { passive: false });
  window.addEventListener('pointermove', handleWindowPointerMove, { passive: false });
  window.addEventListener('pointerup', handleWindowPointerUp, { passive: false });
  window.addEventListener('pointercancel', handleWindowPointerCancel, { passive: false });
  canvas.addEventListener('wheel', handleWheel, { passive: false });
  window.addEventListener('keydown', handleKeyDown);
  window.addEventListener('keyup', handleKeyUp);
  window.addEventListener('blur', handleWindowBlur);
  window.addEventListener('resize', handleResize);

  return () => {
    pullToRefresh.destroy();
    coarsePointerQuery.removeEventListener?.('change', updateCoarsePointerMode);
    canvas.removeEventListener('contextmenu', handleContextMenu);
    canvas.removeEventListener('pointerdown', handlePointerDown);
    canvas.removeEventListener('pointerup', handlePointerUp);
    canvas.removeEventListener('pointermove', handlePointerMove);
    canvas.removeEventListener('pointerleave', handlePointerLeave);
    canvas.removeEventListener('pointerout', handlePointerOut);
    canvas.removeEventListener('pointercancel', handlePointerCancel);
    window.removeEventListener('pointermove', handleWindowPointerMove);
    window.removeEventListener('pointerup', handleWindowPointerUp);
    window.removeEventListener('pointercancel', handleWindowPointerCancel);
    canvas.removeEventListener('wheel', handleWheel);
    window.removeEventListener('keydown', handleKeyDown);
    window.removeEventListener('keyup', handleKeyUp);
    window.removeEventListener('blur', handleWindowBlur);
    window.removeEventListener('resize', handleResize);
  };
}
